"""HSC mathematics: constraints, inverse reasoning and connected concepts."""
from .core import add,Q,F,fmt
from math import comb,factorial

c='math-1-01'
add(c,'rank-one-determinant',lambda n:Q(f'A=[[{n+1},{n}],[1,2]]। det(A⁻¹·3Aᵀ) কত?',9,[3,F(9,n+2),9*(n+2)],'det(A)=n+2≠0। det(A⁻¹)det(3Aᵀ)=det(A)⁻¹·3²det(A)=9।'),kind='structural')
add(c,'singular-parameter',lambda n:Q(f'A=[[x,{n}],[{n+1},x+1]] singular এবং x>0। x কত?',n,[-n-1,n+1,n*(n+1)],'Singular হলে x(x+1)−n(n+1)=0=(x−n)(x+n+1)। ধনাত্মক মূল n।'))
add(c,'inverse-trace',lambda n:Q(f'A একটি 2×2 invertible matrix, tr(A)={3*n}, det(A)={n*n}। tr(A⁻¹) কত?',F(3,n),[3*n,F(1,n*n),F(n,3)],'2×2 matrix-এর adjugate-এর trace=tr(A)। তাই tr(A⁻¹)=tr(A)/det(A)=3/n।'))
add(c,'cayley-square-trace',lambda n:Q(f'2×2 matrix A-এর trace={n+2}, determinant={n}। tr(A²) কত?',n*n+2*n+4,[(n+2)**2,n*n+4,n*n+4*n+4+2*n],'Cayley–Hamilton থেকে A²−tr(A)A+det(A)I=0। trace নিলে tr(A²)=tr(A)²−2det(A)।'),'hard','structural')
add(c,'nilpotent-inverse',lambda n:Q(f'A=I+N, N²=0, N=[[0,{n}],[0,0]]। (A⁻¹)₁₂ কত?',-n,[n,0,F(-1,n)],'(I+N)(I−N)=I−N²=I। অতএব A⁻¹=I−N; (1,2) উপাদান −n।'))
add(c,'det-shift',lambda n:Q(f'2×2 matrix A-এর det(A)={n}, tr(A)=3। det(A+2I) কত?',n+10,[n+4,n+6,n+2],'2×2-এর det(A+tI)=det(A)+t tr(A)+t²। t=2 বসালে n+6+4।'),'hard','structural')
add(c,'linear-system-parameter',lambda n:Q(f'x+2y={n+4}, 3x+ky={3*n+12}। অসংখ্য সমাধান পেতে k কত?',6,[2,3,n+4],'দ্বিতীয় সমীকরণ প্রথমটির ঠিক 3 গুণ হলে রেখাদ্বয় সমাপতিত। তাই k=3×2=6।'))
add(c,'idempotent-eigen',lambda n:Q(f'A²=A একটি 2×2 matrix, tr(A)=1। det({n}I+A) কত?',n*(n+1),[n*n,(n+1)**2,n*(n-1)],'Idempotent matrix-এর eigenvalue 0 বা 1। trace=1 হওয়ায় দুটি eigenvalue 0,1; determinant n(n+1)।'),'hard','structural')
add(c,'skew-square',lambda n:Q(f'A=[[0,{n}],[-{n},0]]। A²-এর (2,2) উপাদান কত?',-n*n,[n*n,-2*n,0],'সরাসরি গুণে A²=−n²I। চিহ্ন হারালে ভুল করে +n² পাওয়া যায়।'))
add(c,'adjugate-det',lambda n:Q(f'A একটি 3×3 matrix এবং det(A)={n}। det(adj(A)) কত?',n*n,[n,n**3,F(1,n)],'A·adj(A)=det(A)I। determinant নিলে det(adj(A))=det(A)^(3−1)=n²।'))

c='math-1-02'
add(c,'projection-residual',lambda n:Q(f'a=({n},2,1), b=(1,0,0)। b-এর লম্ব দিকে a-এর উপাংশের দৈর্ঘ্যের বর্গ কত?',5,[n*n,n*n+5,4],'Projection onto b=(n,0,0); perpendicular component=(0,2,1), norm²=4+1=5।'))
add(c,'orthogonal-parameter',lambda n:Q(f'a=(x,{n},1), b=(2,−1,3)। a⊥b হলে x কত?',F(n-3,2),[F(n+3,2),n-3,F(3-n,2)],'লম্ব vector-এর dot product শূন্য: 2x−n+3=0। তাই x=(n−3)/2।'))
add(c,'cross-area',lambda n:Q(f'a=({n},1,0), b=(0,1,2)। এদের গঠিত ত্রিভুজের ক্ষেত্রফলের বর্গ কত?',F(5*n*n+4,4),[5*n*n+4,F(5*n*n+4,2),F(n*n+4,4)],'a×b=(2,−2n,n), norm²=4+5n²। ত্রিভুজের ক্ষেত্রফল=½|a×b|; বর্গে factor ¼।'))
add(c,'triple-coplanar',lambda n:Q(f'a=(1,0,{n}), b=(0,1,2), c=(3,4,x)। সমতলীয় হতে x কত?',3*n+8,[3*n+4,3*n-8,8-3*n],'c=3a+4b হতে হবে; তৃতীয় উপাদান x=3n+8। scalar triple product-ও শূন্য হয়।'))
add(c,'sum-difference-angle',lambda n:Q(f'|a|={n}, |b|={n} এবং a·b={F(n*n,2)}। a+b ও a−b-এর মধ্যবর্তী কোণ কত?','90°',['60°','120°','0°'],'(a+b)·(a−b)=|a|²−|b|²=0। উভয় vector শূন্য নয়; তাই তারা লম্ব।'),'medium','conceptual')
add(c,'resultant-inverse',lambda n:Q(f'|a|=3, |b|=4 এবং |{n}a+{n}b|=5×{n}। a·b কত?',0,[12,-12,7],'|a+b|²=9+16+2a·b=25। ফলে dot product শূন্য; scaling n কেটে যায়।'))
add(c,'direction-cosines',lambda n:Q(f'এক vector-এর direction ratio 2:{n}:2। y-axis-এর direction cosine-এর বর্গ কত?',F(n*n,n*n+8),[F(n,n+4),F(n*n,n*n+4),F(8,n*n+8)],'Direction cosine m=n/√(n²+8)। normalization-এর সব তিনটি উপাংশ রাখতে হয়।'))
add(c,'unit-cross',lambda n:Q(f'a=({n},0,0), b=(0,3,4)। a×b-এর z-axis direction cosine কত?',F(3,5),[F(4,5),F(-3,5),1],'a×b=(0,−4n,3n); magnitude=5n। z direction cosine=3n/(5n)=3/5।'))
add(c,'work-projection',lambda n:Q(f'F=({n},2,−1) N এবং r=(2,−1,{n}) m। কাজ কত J?',n-2,[3*n-2,n+2,3*n+2],'কাজ F·r=2n−2−n=n−2। vector-এর মানদ্বয় গুণ করলে দিকের তথ্য হারায়।'))
add(c,'vector-identity',lambda n:Q(f'|a|²={n}, |b|²={n+3}, a·b=1। |a×b|² কত?',n*(n+3)-1,[n*(n+3)+1,2*n+3,n*(n+3)],'Lagrange identity: |a×b|²=|a|²|b|²−(a·b)²=n(n+3)−1।'))

c='math-1-03'
add(c,'reflected-point',lambda n:Q(f'P=({n},1)-এর x+y=0 রেখায় প্রতিবিম্ব কোনটি?',f'(−1,−{n})',[f'(1,{n})',f'(−{n},−1)',f'({n},−1)'],'x+y=0-এ reflection map (x,y)→(−y,−x)। P বসালে (−1,−n)।'))
add(c,'parallel-distance',lambda n:Q(f'3x+4y={n} ও 3x+4y={n+10} রেখার দূরত্ব কত?',2,[10,5,F(1,2)],'সমান্তরাল রেখার দূরত্ব |c₂−c₁|/√(a²+b²)=10/5=2।'))
add(c,'intersection-area',lambda n:Q(f'x/{n}+y/4=1 রেখা ও অক্ষদ্বয়ের গঠিত ত্রিভুজের ক্ষেত্রফল কত?',2*n,[4*n,F(n,2),n*n],'Intercept n ও 4। ত্রিভুজের ক্ষেত্রফল ½×n×4=2n।'))
add(c,'pencil-constraint',lambda n:Q(f'x+y={n} এবং x−y=2 রেখার ছেদবিন্দুগামী, x-axis-এর সমান্তরাল রেখার y-intercept কত?',F(n-2,2),[F(n+2,2),n-2,2-n],'সমীকরণ বিয়োগে 2y=n−2। অনুভূমিক রেখায় y এই ধ্রুব মানই থাকে।'))
add(c,'foot-perpendicular',lambda n:Q(f'({n},0) থেকে x=y রেখায় লম্বের পাদবিন্দু কোনটি?',f'({fmt(F(n,2))},{fmt(F(n,2))})',[f'({n},{n})','(0,0)',f'({n},0)'],'x=y-এর direction (1,1)-এ projection: [(n,0)·(1,1)]/2×(1,1)।'))
add(c,'angle-bisector-distance',lambda n:Q(f'P=({n},2) বিন্দু x-axis ও y-axis থেকে সমদূরবর্তী হতে n-এর ধনাত্মক মান কত?',2,[1,4,0],'অক্ষদ্বয় থেকে দূরত্ব যথাক্রমে |y| ও |x|। তাই |n|=2 এবং n>0 থেকে 2।'))
add(c,'orthocentre',lambda n:Q(f'ত্রিভুজের শীর্ষ (0,0),({n},0),(0,4)। লম্বকেন্দ্র কোথায়?','(0,0)',[f'({n},4)',f'({fmt(F(n,2))},2)','(0,4)'],'প্রথম শীর্ষে দুই বাহু পরস্পর লম্ব। সমকোণী ত্রিভুজের লম্বকেন্দ্র সমকোণী শীর্ষ।'),'medium','conceptual')
add(c,'centroid-line',lambda n:Q(f'A=(0,0), B=(6,0), C=({n},9)। centroid-এর y-coordinate কত?',3,[9,F(9,2),n],'Centroid-এর coordinates শীর্ষগুলোর arithmetic mean। y=(0+0+9)/3=3।'))
add(c,'normalised-line',lambda n:Q(f'5x+12y={13*n} রেখার origin থেকে দূরত্ব কত?',n,[13*n,F(n,13),n*n],'লম্ব দূরত্ব |13n|/√(25+144)=13n/13=n; coefficient norm দরকার।'))
add(c,'section-external',lambda n:Q(f'A=(0,0), B=({n},0)। P বহির্বিভক্ত করে AP:PB=3:2। P-এর x-coordinate কত?',3*n,[F(3*n,5),-3*n,2*n],'External section formula x=(3xB−2xA)/(3−2)=3n। P, B-এর বাইরে থাকে।'))

c='math-1-04'
add(c,'radical-axis',lambda n:Q(f'x²+y²={n*n} এবং x²+y²−4x={n*n-8} বৃত্তদ্বয়ের common chord-এর রেখা কোনটি?','x=2',['x=−2','y=2','x=4'],'দুটি সমীকরণ বিয়োগে −4x=−8। common chord radical axis x=2।'))
add(c,'tangent-power',lambda n:Q(f'x²+y²=9 বৃত্তের বাইরে P=({n+3},0)। tangent length-এর বর্গ কত?',n*n+6*n,[(n+3)**2,n*n,n*n+6*n+18],'Power of point PT²=OP²−r²=(n+3)²−9=n²+6n।'))
add(c,'circle-completion',lambda n:Q(f'x²+y²−{2*n}x+6y+{n*n-7}=0 বৃত্তের ব্যাস কত?',8,[4,16,n],'Completing square: (x−n)²+(y+3)²=16। radius 4, diameter 8।'))
add(c,'chord-midpoint',lambda n:Q(f'x²+y²={n*n+9} বৃত্তের x={n} chord-এর দৈর্ঘ্য কত?',6,[3,2*n,n+3],'x=n বসিয়ে y²=9; প্রান্ত y=±3। তাই chord length=3−(−3)=6।'))
add(c,'orthogonal-circles',lambda n:Q(f'দুটি বৃত্তের ব্যাসার্ধ {n} ও 3; তারা orthogonal। কেন্দ্রদ্বয়ের দূরত্বের বর্গ কত?',n*n+9,[(n+3)**2,(n-3)**2,n*n-9],'Orthogonal circle-এ common point-এর radii পরস্পর লম্ব; d²=r₁²+r₂²।'))
add(c,'tangent-intercept',lambda n:Q(f'x²+y²={25*n*n} বৃত্তের ({3*n},{4*n}) বিন্দুতে tangent-এর x-intercept কত?',F(25*n,3),[F(25*n,4),3*n,5*n],'Tangent xx₁+yy₁=r²: 3nx+4ny=25n²। y=0 দিলে x=25n/3।'))
add(c,'point-circle-position',lambda n:Q(f'(x−{n})²+y²=25 বৃত্তের তুলনায় P=({n+3},4) কোথায়?','বৃত্তের উপর',['বৃত্তের ভিতরে','বৃত্তের বাইরে','কেন্দ্রে'],'কেন্দ্র থেকে দূরত্ব²=3²+4²=25=r²। অতএব P পরিধির উপর।'),'medium','conceptual')
add(c,'diameter-equation',lambda n:Q(f'ব্যাসের প্রান্ত (0,0),({2*n},4)। বৃত্তের কেন্দ্র কোনটি?',f'({n},2)',[f'({2*n},4)',f'({n},4)',f'({2*n},2)'],'ব্যাসের মধ্যবিন্দুই কেন্দ্র: ((0+2n)/2,(0+4)/2)=(n,2)।'))
add(c,'tangent-condition',lambda n:Q(f'x²+y²={n*n} বৃত্তে 3x+4y=c tangent এবং c>0। c কত?',5*n,[n,25*n,3*n],'কেন্দ্র origin থেকে রেখার দূরত্ব c/5=radius n। ধনাত্মক c=5n।'))
add(c,'concentric-annulus',lambda n:Q(f'সমকেন্দ্রিক দুই বৃত্তের ব্যাসার্ধ {n+1} ও {n}। বলয়ের ক্ষেত্রফল/π কত?',2*n+1,[1,(2*n+1)**2,n+1],'Annulus area=π[(n+1)²−n²]=π(2n+1)। radii-এর পার্থক্যের বর্গ নয়।'))

c='math-1-05'
add(c,'nonadjacent-selection',lambda n:Q(f'সারিতে {n+3}টি স্থান। পাশাপাশি নয় এমন 2টি স্থান কতভাবে বাছা যায়?',comb(n+2,2),[comb(n+3,2),n+2,comb(n+1,2)],'মোট C(n+3,2) pair থেকে n+2 adjacent pair বাদ: C(n+2,2)।'),'hard')
add(c,'at-least-one',lambda n:Q(f'{n} ছেলে ও 3 মেয়ে থেকে 3 জনের দলে অন্তত 1 মেয়ে থাকবে। দলসংখ্যা কত?',comb(n+3,3)-comb(n,3),[comb(n+3,3),3*comb(n,2),comb(n+3,3)-1],'Complement: সব দল C(n+3,3) থেকে all-boy দল C(n,3) বাদ।'))
add(c,'exactly-two-special',lambda n:Q(f'{n} সাধারণ ও 4 বিশেষ সদস্য থেকে 5 জনের দলে ঠিক 2 বিশেষ সদস্য। কত দল?',6*comb(n,3),[4*comb(n,3),6*comb(n,2),comb(n+4,5)],'বিশেষ 4 থেকে 2 বাছতে C(4,2)=6; সাধারণ n থেকে 3 বাছতে C(n,3)।'))
add(c,'ordered-with-fixed',lambda n:Q(f'{n+3}টি ভিন্ন বই থেকে 3টি সাজাতে নির্দিষ্ট বইটি মাঝখানে অবশ্যই থাকবে। উপায় কত?',(n+2)*(n+1),[3*(n+2)*(n+1),comb(n+2,2),(n+3)*(n+2)],'মাঝের বই স্থির। বাকি n+2 থেকে দুটো orderedভাবে বাছতে P(n+2,2)।'))
add(c,'digit-no-zero',lambda n:Q(f'0,1,2,3,4 অঙ্ক দিয়ে পুনরাবৃত্তি ছাড়া {3 if n%2 else 4} অঙ্কের সংখ্যা কত?',48 if n%2 else 96,[60 if n%2 else 120,36 if n%2 else 72,64 if n%2 else 256],'প্রথম স্থানে শূন্য নিষিদ্ধ: 4 choice। পরের স্থানগুলোতে অবশিষ্ট অঙ্কের permutation; 4·P(4,r−1)।'))
add(c,'stars-bars-positive',lambda n:Q(f'x+y+z={n+3}, যেখানে x,y,z ধনাত্মক পূর্ণসংখ্যা। ordered solution কত?',comb(n+2,2),[comb(n+5,2),comb(n+3,2),(n+3)**2],'x′=x−1 ইত্যাদি দিলে x′+y′+z′=n। nonnegative stars-and-bars C(n+2,2)।'))
add(c,'committee-exclusion',lambda n:Q(f'{n+3} জন থেকে 3 জনের committee; নির্দিষ্ট দুইজন একসঙ্গে থাকতে পারবে না। দল কত?',comb(n+3,3)-(n+1),[comb(n+3,3),comb(n+1,3),comb(n+3,3)-2],'নিষিদ্ধ দল: দুইজন fixed, বাকি একজন n+1 উপায়। মোট থেকে এগুলো বাদ।'))
add(c,'path-count',lambda n:Q(f'Grid-এ origin থেকে ({n},2) যেতে কেবল ডানে ও উপরে unit step। shortest path কত?',comb(n+2,2),[n*n,2*n,comb(n+2,1)],'মোট n+2 step-এর মধ্যে upward দুইটির স্থান বাছতে C(n+2,2)।'))
add(c,'binary-adjacent-block',lambda n:Q(f'{n}টি ভিন্ন বই ও দুইটি ভিন্ন অভিধানকে সারিতে সাজাতে অভিধান দুটো পাশাপাশি থাকবে। উপায় কত?',f'2×{n+1}!', [f'{n+2}!',f'{n+1}!',f'2×{n}!'],'অভিধানকে এক block ধরলে n+1 unit, তাদের permutation (n+1)!; block-এর ভিতরে 2!।'))
add(c,'binomial-double-choice',lambda n:Q(f'{n+2} জন থেকে captain ও vice-captain আলাদা ব্যক্তি। দায়িত্ব বণ্টন কত?',(n+2)*(n+1),[comb(n+2,2),(n+2)**2,2*(n+2)],'দুই দায়িত্ব ordered: প্রথম n+2 choice, দ্বিতীয় n+1। combination নিলে পদভেদ হারায়।'))

c='math-1-06'
add(c,'triangle-cosine',lambda n:Q(f'ত্রিভুজে a={n}, b={n+1}, অন্তর্ভুক্ত কোণ 60°। তৃতীয় বাহুর বর্গ কত?',n*n+n+1,[(2*n+1)**2,n*n+(n+1)**2,n*n+n],'Cosine rule c²=a²+b²−2ab cos60°=a²+b²−ab=n²+n+1।'))
add(c,'inradius-right',lambda n:Q(f'সমকোণী ত্রিভুজের বাহু {3*n},{4*n},{5*n}। অন্তঃব্যাসার্ধ কত?',n,[2*n,3*n,F(n,2)],'ক্ষেত্রফল=6n² এবং semiperimeter=6n। r=Δ/s=n; অথবা (a+b−c)/2।'))
add(c,'circumradius-right',lambda n:Q(f'সমকোণী ত্রিভুজে লম্ব বাহু {5*n}, {12*n}। পরিবৃত্তের ব্যাসার্ধ কত?',F(13*n,2),[13*n,F(17*n,2),6*n],'Hypotenuse=13n। সমকোণী ত্রিভুজের circumradius hypotenuse-এর অর্ধেক।'))
add(c,'half-angle-product',lambda n:Q(f'একটি ত্রিভুজের inradius r={n}, semiperimeter s={7*n}। tan(A/2)tan(B/2)tan(C/2) কত?',F(1,7),[7,F(1,49),F(1,3)],'ত্রিভুজে tan(A/2)tan(B/2)tan(C/2)=r/s। তাই n/(7n)=1/7।'),'hard')
add(c,'sine-law-radius',lambda n:Q(f'ত্রিভুজের এক বাহু {n} এবং বিপরীত কোণ 30°। circumdiameter কত?',2*n,[n,F(n,2),4*n],'Extended sine rule a/sinA=2R। sin30°=½ থেকে diameter=2n।'))
add(c,'area-two-sides',lambda n:Q(f'দুই বাহু {2*n}, {3*n}; অন্তর্ভুক্ত কোণ 30°। ক্ষেত্রফল কত?',F(3*n*n,2),[3*n*n,6*n*n,F(3*n,2)],'Δ=½ab sinC=½·2n·3n·½=3n²/2। দুটি অর্ধেক factor রাখতে হয়।'))
add(c,'sine-cosine-product',lambda n:Q(f'0<θ<π/2 এবং sinθ+cosθ={fmt(F(n+1,n))}। sin2θ কত?',F(2*n+1,n*n),[F(n+1,n),F(1,n*n),F(n*n+2*n+1,n*n)],'(sinθ+cosθ)²=1+sin2θ। তাই sin2θ=(n+1)²/n²−1=(2n+1)/n²।'))
add(c,'cot-sum',lambda n:Q(f'ত্রিভুজে cotA={n}, cotB=2। cotC কত?',F(1-2*n,n+2),[F(2*n-1,n+2),n+2,F(n+2,2*n-1)],'A+B=π−C। cot(A+B)=(cotA cotB−1)/(cotA+cotB)=−cotC।'))
add(c,'altitude-area',lambda n:Q(f'3:4:5 অনুপাতের সমকোণী ত্রিভুজের hypotenuse {5*n}। তার উপর altitude কত?',F(12*n,5),[3*n,4*n,F(6*n,5)],'দুইভাবে ক্ষেত্রফল: ½·3n·4n=½·5n·h। ফলে h=12n/5।'))
add(c,'triangle-ratio',lambda n:Q(f'A=30°, B=90° এবং a={n}। b কত?',2*n,[n,F(n,2),3*n],'Sine rule b/a=sin90°/sin30°=2। বিপরীত বাহু-অনুপাত কোণের অনুপাত নয়।'))

c='math-1-07'
add(c,'tan-addition',lambda n:Q(f'tanA={n}, tanB=1/2, এবং denominator শূন্য নয়। tan(A+B) কত?',F(2*n+1,2-n),[F(2*n+1,2+n),F(2*n-1,2+n),F(2*n-1,2-n)],'tan(A+B)=(tanA+tanB)/(1−tanA tanB)=(2n+1)/(2−n)।'),'hard')
add(c,'tan-double',lambda n:Q(f'tanθ=1/{n}। tan2θ কত?',F(2*n,n*n-1),[F(2,n),F(2*n,n*n+1),F(n*n-1,2*n)],'Double-angle: tan2θ=2t/(1−t²)=2n/(n²−1); এখানে n>1।'))
add(c,'sin-double-rational',lambda n:Q(f'tanθ={n} এবং θ acute। sin2θ কত?',F(2*n,1+n*n),[F(2*n,1-n*n),F(n,1+n*n),F(n*n-1,n*n+1)],'sin2θ=2tanθ/(1+tan²θ)=2n/(1+n²)। acute θ মানে 2θ সর্বদা acute নয়।'))
add(c,'triple-angle',lambda n:Q(f'cosθ=1/{n}। cos3θ কত?',F(4-3*n*n,n**3),[F(3*n*n-4,n**3),F(3,n),F(4,n**3)],'cos3θ=4cos³θ−3cosθ। 4/n³−3/n=(4−3n²)/n³।'))
add(c,'sum-to-product',lambda n:Q(f'sin({n}θ)+sin(({n+2})θ) কোনটির সমান?',f'2sin(({n+1})θ)cosθ',[f'2cos(({n+1})θ)sinθ',f'2sinθ cos(({n+1})θ)',f'sin(({2*n+2})θ)'],'Sum-to-product: sinU+sinV=2sin((U+V)/2)cos((U−V)/2)।'))
add(c,'product-integrated-angle',lambda n:Q(f'2cos({n}θ)cosθ কোনটির সমান?',f'cos(({n+1})θ)+cos(({n-1})θ)',[f'cos(({n+1})θ)−cos(({n-1})θ)',f'sin(({n+1})θ)+sin(({n-1})θ)',f'cos(({2*n})θ)'],'Product-to-sum: 2cosU cosV=cos(U+V)+cos(U−V)। minus sign দিলে sine-product identity হয়।'))
add(c,'period-transformed',lambda n:Q(f'f(x)=sin({n}x)+cos({2*n}x)। fundamental period কত?',f'2π/{n}',[f'π/{n}',f'4π/{n}',f'2π/{2*n}'],'sin(nx)-এর period 2π/n, cos(2nx)-এর π/n; common fundamental period 2π/n।'))
add(c,'phase-max',lambda n:Q(f'f(x)={3*n}sinx+{4*n}cosx। সর্বোচ্চ মান কত?',5*n,[7*n,n,25*n*n],'a sinx+b cosx-এর maximum √(a²+b²)=√(9n²+16n²)=5n।'))
add(c,'double-cot',lambda n:Q(f'cotθ={n}। cot2θ কত?',F(n*n-1,2*n),[F(n*n+1,2*n),F(2*n,n*n-1),2*n],'cot2θ=(cot²θ−1)/(2cotθ)=(n²−1)/(2n)। inverse নিলে tan2θ পাওয়া যায়।'))
add(c,'half-angle-tan',lambda n:Q(f'sinθ={fmt(F(2*n,n*n+1))}, cosθ={fmt(F(n*n-1,n*n+1))}, 0<θ<π/2। tan(θ/2) কত?',F(1,n),[n,F(2,n),F(1,n*n)],'tan(θ/2)=sinθ/(1+cosθ)=[2n/(n²+1)]/[2n²/(n²+1)]=1/n।'))

c='math-1-08'
add(c,'rational-domain',lambda n:Q(f'f(x)=√({n}−x)/(x−2)। domain কোনটি?',f'(−∞,{n}] ∖ {{2}}',[f'[2,{n}]',f'({n},∞)',f'ℝ ∖ {{2,{n}}}'],'Square root requires x≤n; denominator excludes x=2। উভয় শর্তের intersection নিতে হয়।'))
add(c,'composition-inverse',lambda n:Q(f'f(x)=2x+{n}, g(x)=x²। (g∘f)(1) কত?',(n+2)**2,[2+n*n,2*n+1,n*n+4],'প্রথমে f(1)=n+2, পরে g(f(1))=(n+2)²। composition-এর ক্রম বদলানো যাবে না।'))
add(c,'inverse-rational',lambda n:Q(f'f(x)=(x+{n})/(x−1)। f⁻¹(2) কত?',n+2,[n-2,F(n+2,2),2-n],'2=(x+n)/(x−1) ⇒2x−2=x+n⇒x=n+2। এই x≠1।'))
add(c,'quadratic-range',lambda n:Q(f'f(x)=x²−{2*n}x+{n*n+3}, x∈ℝ। range কোনটি?','[3,∞)',['[0,∞)',f'[{n*n+3},∞)','ℝ'],'Completing square f=(x−n)²+3। minimum 3 at x=n, তাই range [3,∞)।'))
add(c,'abs-preimages',lambda n:Q(f'f(x)=|x−{n}|+|x+{n}|। f(x)={2*n} সমীকরণের solution set কোনটি?',f'[−{n},{n}]',[f'{{−{n},{n}}}','{0}','ℝ'],'−n≤x≤n-এ দুই দূরত্বের যোগ 2n। বাইরে যোগ বড়; শুধু endpoints নয় পুরো interval।'),'hard','piecewise')
add(c,'piecewise-continuity',lambda n:Q(f'f(x)=x², x<{n}; f(x)=kx, x≥{n}। x={n}-এ continuous হলে k কত?',n,[n*n,2*n,F(1,n)],'বাম limit=n²; ডান value=kn। n≠0 হলে kn=n² থেকে k=n।'))
add(c,'even-shift',lambda n:Q(f'f(x)=(x−{n})²+1। graph-এর symmetry axis কোনটি?',f'x={n}',[f'y={n}','x=0',f'x=−{n}'],'Parabola vertex (n,1)। x=n±t-এ সমান value; তাই symmetry axis x=n।'))
add(c,'log-domain',lambda n:Q(f'f(x)=ln((x−{n})({n+2}−x))। domain কোনটি?',f'({n},{n+2})',[f'[{n},{n+2}]',f'(−∞,{n})∪({n+2},∞)','ℝ'],'Log argument অবশ্যই positive; product positive হয় দুই root-এর মাঝে, endpoints বাদ।'))
add(c,'injective-restriction',lambda n:Q(f'f(x)=(x−{n})², domain [{n},∞)। inverse function কোনটি?',f'f⁻¹(y)={n}+√y',[f'{n}−√y',f'±√y',f'√(y−{n})'],'domain x≥n বলে x−n≥0। y=(x−n)² থেকে positive branch x=n+√y।'))
add(c,'floor-limit',lambda n:Q(f'f(x)=⌊x⌋। x={n}-এ বাম limit ও f({n})-এর পার্থক্য f({n})−limₓ→{n}⁻f(x) কত?',1,[0,n,-1],'Integer n-এর ঠিক বাঁয়ে floor=n−1; n-এ value n। jump size=1।'),'medium','graph_reasoning')

c='math-1-09'
add(c,'implicit-tangent',lambda n:Q(f'x²+xy+y²={3*n*n} বক্ররেখার ({n},{n}) বিন্দুতে tangent slope কত?',-1,[1,-2,F(-1,2)],'Implicit derivative: 2x+y+(x+2y)y′=0। x=y=n দিলে y′=−3n/(3n)=−1।'))
add(c,'log-derivative',lambda n:Q(f'y=x^{n}, x>0। x y′/y কত?',n,[n-1,n*n,F(1,n)],'lny=n lnx; derivative y′/y=n/x। তাই xy′/y=n। logarithmic sensitivity।'))
add(c,'inverse-derivative',lambda n:Q(f'f(x)=x³+x, g=f⁻¹। g′({n**3+n}) কত?',F(1,3*n*n+1),[3*n*n+1,F(1,n*n+1),F(1,3*n*n)],'Inverse derivative g′(f(n))=1/f′(n)=1/(3n²+1); evaluation point আগে চিনতে হয়।'),'hard')
add(c,'stationary-classify',lambda n:Q(f'f(x)=x³−{3*n*n}x। x={n} stationary point-এর ধরন কী?','স্থানীয় সর্বনিম্ন',['স্থানীয় সর্বোচ্চ','inflection point','stationary নয়'],'f′=3x²−3n²; n-এ শূন্য। f″(n)=6n>0 বলে স্থানীয় সর্বনিম্ন।'),'medium','classification')
add(c,'normal-gradient',lambda n:Q(f'y=x² বক্ররেখায় x={n} বিন্দুতে normal slope কত?',F(-1,2*n),[2*n,F(1,2*n),-2*n],'Tangent slope y′=2n। normal-এর slope negative reciprocal −1/(2n)।'))
add(c,'related-rates',lambda n:Q(f'বৃত্তের radius {n} cm এবং dr/dt=3 cm/s। (dA/dt)/π কত cm²/s?',6*n,[3*n,6*n*n,3*n*n],'A=πr²; chain rule dA/dt=2πr dr/dt=6πn। r ও dr/dt আলাদা।'))
add(c,'max-product',lambda n:Q(f'x,y>0 ও x+y={2*n}। xy-এর সর্বোচ্চ মান কত?',n*n,[2*n,n,F(n*n,2)],'xy=x(2n−x)=n²−(x−n)²। maximum at x=y=n, মান n²।'))
add(c,'parametric-slope',lambda n:Q(f'x=t², y=t³। t={n}-এ dy/dx কত?',F(3*n,2),[3*n*n,2*n,F(2,3*n)],'dy/dx=(dy/dt)/(dx/dt)=3t²/(2t)=3t/2। derivative শুধু y-এর নয়।'))
add(c,'derivative-limit',lambda n:Q(f'limₕ→0 [({n}+h)⁴−{n**4}]/h কত?',4*n**3,[n**4,4*n*n,n**3],'এটি f(x)=x⁴-এর x=n-এ derivative definition। তাই f′(n)=4n³।'))
add(c,'log-composite',lambda n:Q(f'y=ln(1+x²)। x={n}-এ derivative কত?',F(2*n,1+n*n),[F(1,1+n*n),2*n,F(2*n,n*n)],'Chain rule: y′=1/(1+x²)·2x। outer ও inner উভয় derivative রাখতে হয়।'))

c='math-1-10'
add(c,'symmetry-integral',lambda n:Q(f'∫₀^{n} x/({n}+x) dx + ∫₀^{n} ({n}−x)/({2*n}−x) dx কত?',f'{2*n}−{2*n}ln2',[f'{n}ln2',f'{n}−{2*n}ln2',f'{n}'],'দ্বিতীয় integral-এ u=n−x দিলে প্রথমটির সমান। প্রথম মান n−n ln2; যোগ 2n−2nln2।'),'hard')
add(c,'odd-integral',lambda n:Q(f'∫₋{n}^{n} (x³+x)/(1+x²) dx কত?',0,[n*n,2*n,n],'Integrand odd: denominator even এবং numerator odd। symmetric limits-এর integral শূন্য।'))
add(c,'substitution-log',lambda n:Q(f'∫₀¹ {2*n}x/(1+{n}x²) dx কত?',f'ln{n+1}',[f'{n}ln2',f'ln{n}',f'2ln{n+1}'],'u=1+nx², du=2nx dx। limits 1 থেকে n+1; integral ln(n+1)।'))
add(c,'area-crossing',lambda n:Q(f'y=x−{n}, x=0, x={2*n} ও x-axis দ্বারা bounded মোট ক্ষেত্রফল কত?',n*n,[0,2*n*n,F(n*n,2)],'x=n-এ sign বদলায়। দুটি সমান triangle-এর area ½n²+½n²=n²; signed integral শূন্য।'),'hard','area_reasoning')
add(c,'quadratic-area',lambda n:Q(f'y={n*n}−x² ও x-axis-এর enclosed ক্ষেত্রফল কত?',F(4*n**3,3),[F(2*n**3,3),2*n**3,F(4*n*n,3)],'Intersections x=±n। ∫₋ₙⁿ(n²−x²)dx=2[n²x−x³/3]₀ⁿ=4n³/3।'))
add(c,'integration-parts',lambda n:Q(f'∫₀¹ x^{n}lnx dx কত?',F(-1,(n+1)**2),[F(1,(n+1)**2),F(-1,n+1),F(-1,n*n)],'Parts: u=lnx, dv=xⁿdx। boundary term 0 এবং −(1/(n+1))∫₀¹xⁿdx=−1/(n+1)²।'),'hard')
add(c,'fundamental-chain',lambda n:Q(f'F(x)=∫₀^(x²)(t+{n})dt। F′(1) কত?',2*(n+1),[n+1,2*n,2+n*n],'FTC ও chain rule: F′(x)=(x²+n)·2x। x=1 বসালে 2(n+1)।'))
add(c,'reciprocal-pair',lambda n:Q(f'∫₁^{n} dx/[x(x+1)] কত?',f'ln({2*n}/{n+1})',[f'ln{n}',f'ln({n+1}/2)',f'ln({n+1}/{2*n})'],'Partial fraction 1/[x(x+1)]=1/x−1/(x+1)। endpoints বসিয়ে ln(2n/(n+1))।'))
add(c,'mean-value-integral',lambda n:Q(f'f(x)=x²-এর [0,{n}] interval-এ average value কত?',F(n*n,3),[F(n**3,3),F(n*n,2),n*n],'Average value=(1/n)∫₀ⁿx²dx=(1/n)(n³/3)=n²/3; integral নিজে average নয়।'))
add(c,'trig-substitution',lambda n:Q(f'∫₀^(π/2) sinx cos^{n}x dx কত?',F(1,n+1),[F(1,n),F(2,n+1),1],'u=cosx, du=−sinx dx; limits 1→0। ফলে ∫₀¹uⁿdu=1/(n+1)।'))

c='math-2-01'
add(c,'rational-inequality',lambda n:Q(f'(x−{n})/(x+1)≤0-এর solution কোনটি?',f'(−1,{n}]',[f'[−1,{n}]',f'(−∞,−1)∪[{n},∞)',f'[−{n},1)'],'Critical values −1 ও n। sign chart-এ মাঝের interval negative; denominator zero বাদ, numerator zero রাখা হয়।'),'hard','inequality')
add(c,'absolute-band',lambda n:Q(f'|2x−{2*n}|<6-এর solution কোনটি?',f'({n-3},{n+3})',[f'[{n-3},{n+3}]',f'({n-6},{n+6})',f'(−∞,{n-3})∪({n+3},∞)'],'−6<2(x−n)<6; 2 দিয়ে ভাগে n−3<x<n+3। strict inequality-এ endpoint বাদ।'))
add(c,'amgm-reciprocal',lambda n:Q(f'x>0 হলে x+{n*n}/x-এর সর্বনিম্ন মান কত?',2*n,[n,n*n,2*n*n],'AM–GM: x+n²/x≥2√n²=2n। equality x=n-এ, তাই minimum অর্জিত হয়।'))
add(c,'quadratic-always-positive',lambda n:Q(f'x²−{2*n}x+k>0 সকল বাস্তব x-এর জন্য সত্য। k-এর শর্ত কোনটি?',f'k>{n*n}',[f'k≥{n*n}',f'k<{n*n}',f'k>{2*n}'],'Completing square (x−n)²+k−n²। minimum strictly positive চাইলে k>n²; equality দিলে শূন্য হয়।'))
add(c,'log-inequality',lambda n:Q(f'log₁/₂(x−{n})>−1-এর solution কোনটি?',f'({n},{n+2})',[f'({n+2},∞)',f'[{n},{n+2}]',f'(−∞,{n+2})'],'Log domain x>n। base<1 হওয়ায় decreasing; x−n<2, ফলে n<x<n+2।'),'hard','inequality')
add(c,'integer-count',lambda n:Q(f'|x|<{n} শর্তে পূর্ণসংখ্যা x কতটি?',2*n-1,[2*n+1,2*n,n-1],'পূর্ণসংখ্যা −(n−1) থেকে n−1 পর্যন্ত; সংখ্যা (n−1)−(−n+1)+1=2n−1।'))
add(c,'reciprocal-inversion',lambda n:Q(f'x>{n}>0 হলে 1/x-এর সঠিক range কোনটি?',f'(0,1/{n})',[f'(1/{n},∞)',f'[0,1/{n}]',f'(−∞,1/{n})'],'Positive reciprocal order reverses: 0<1/x<1/n। দুই endpoint-ই অপ্রাপ্ত।'))
add(c,'square-root-inequality',lambda n:Q(f'√x>{n}, x বাস্তব। solution কোনটি?',f'x>{n*n}',[f'x>{n}',f'x≥{n*n}',f'x<{n*n}'],'√x≥0 এবং n>0। উভয়দিকে square করা equivalence-preserving; x>n²।'))
add(c,'triangle-inequality-range',lambda n:Q(f'|x−{n}|+|x+{n}|-এর minimum কত?',2*n,[0,n,n*n],'Triangle inequality ≥|(x−n)−(x+n)|=2n। −n≤x≤n-এ equality সত্য।'))
add(c,'cauchy-bound',lambda n:Q(f'x²+y²={n*n}, x,y বাস্তব। 3x+4y-এর maximum কত?',5*n,[7*n,25*n*n,4*n],'Cauchy–Schwarz: (3x+4y)²≤(9+16)(x²+y²)=25n²। direction (3,4)-এ equality।'))

c='math-2-02'
add(c,'vertex-objective',lambda n:Q(f'x,y≥0, x+y≤{n}, 2x+y≤{n+2}। Z=3x+2y-এর maximum কত? (n≥3)',2*n+2,[3*n,2*n,n+2],'Vertices (0,0),(0,n),((n+2)/2,0),(2,n−2)। Z যথাক্রমে 0,2n,1.5n+3,2n+2; শেষটি সর্বোচ্চ।'),'hard','optimisation')
add(c,'resource-slack',lambda n:Q(f'x,y≥0, x+y≤{n}, x≤2। Z=x+3y সর্বোচ্চ হলে x কত?',0,[2,n,1],'প্রতি unit x resource খরচে লাভ 1, y-তে 3। optimum (0,n), যেখানে সব resource y-তে যায়।'))
add(c,'objective-parallel',lambda n:Q(f'x,y≥0, x+2y≤{2*n}। Z=2x+4y-এর maximum কত?',4*n,[2*n,6*n,8*n],'Z=2(x+2y)≤4n। boundary segment x+2y=2n-এর সব point optimal, শুধু একটি vertex নয়।'),'hard','optimisation')
add(c,'feasible-intersection',lambda n:Q(f'x,y≥0; x+y≥{n+2}, x+y≤{n}। feasible region কী?','শূন্য',['bounded triangle','unbounded','একটি সরলরেখা'],'একই x+y একসঙ্গে n+2-এর অন্তত এবং n-এর বেশি নয় হতে পারে না। constraints inconsistent।'),'medium','conceptual')
add(c,'unbounded-maximum',lambda n:Q(f'x,y≥0, x+y≥{n}। Z=x+y maximisation-এর ফল কী?','সসীম maximum নেই',[f'maximum={n}','maximum=0','feasible point নেই'],'Feasible points (t,0), t≥n-এ Z=t ইচ্ছামতো বড়। তাই feasible হলেও maximum unbounded।'),'medium','conceptual')
add(c,'minimum-corner',lambda n:Q(f'x,y≥0, x+2y≥{2*n}। Z=3x+2y-এর minimum কত?',2*n,[6*n,n,4*n],'Boundary endpoints (2n,0),(0,n)-এ Z=6n,2n। feasible region-এ minimum দ্বিতীয় point-এ।'))
add(c,'integer-versus-continuous',lambda n:Q(f'x,y nonnegative integers, 2x+2y≤{2*n+1}। max(x+y) কত?',n,[F(2*n+1,2),n+1,2*n+1],'x+y integer। constraint x+y≤n+½; greatest allowed integer n। continuous relaxation n+½ দেয়।'))
add(c,'binding-dual',lambda n:Q(f'x,y≥0, x+y≤{n}, x≤1। Z=2x+y maximum হলে y কত?',n-1,[n,1,0],'Z=(x+y)+x≤n+1। equality x=1 এবং x+y=n-এ; y=n−1।'))
add(c,'capacity-objective',lambda n:Q(f'x,y≥0, x≤{n}, y≤2। Z=4x−y-এর maximum কত?',4*n,[4*n-2,4*n+2,n],'Objective x বাড়ায়, y কমায়। feasible rectangle-এর (n,0)-এ max=4n।'))
add(c,'intersection-cost',lambda n:Q(f'x,y≥0, x+y≥{n}, x+3y≥{n+4}। Z=2x+3y-এর minimum কত? (n≥3)',2*n+2,[2*n+8,n+4,3*n],'Boundary intersection y=2,x=n−2; Z=2n+2। other corners (n+4,0),(0,n) cost 2n+8,3n; intersection minimum।'),'hard','optimisation')

c='math-2-03'
add(c,'modulus-quotient',lambda n:Q(f'z=({n}+i)/({n}−i)। |z| কত?',1,[n,F(n*n+1,n*n-1),n*n+1],'Numerator ও denominator conjugate এবং সমান modulus। quotient modulus=1; denominator শূন্য নয়।'))
add(c,'conjugate-inverse',lambda n:Q(f'z={n}+2i। 1/z-এর imaginary part কত?',F(-2,n*n+4),[F(2,n*n+4),F(-1,2),F(-n,n*n+4)],'1/z=(n−2i)/(n²+4)। imaginary coefficient −2/(n²+4); conjugate নেওয়া জরুরি।'))
add(c,'real-parameter',lambda n:Q(f'({n}+i)(x+2i) বাস্তব হতে x কত?',-2*n,[2*n,-n,0],'Product=(nx−2)+i(2n+x)। imaginary part zero হলে x=−2n।'))
add(c,'unit-circle-real',lambda n:Q(f'|z|=1 এবং Re(z)=1/{n}। Re(z²) কত?',F(2-n*n,n*n),[F(2+n*n,n*n),F(1,n*n),F(n*n-2,n*n)],'z·z̄=1। Re(z²)=2(Re z)²−1=2/n²−1। De Moivre-এর cos2θ identity।'))
add(c,'argument-quadrant',lambda n:Q(f'z=−{n}+{n}i। principal argument কত?','3π/4',['π/4','−π/4','−3π/4'],'Real negative, imaginary positive ⇒ quadrant II; reference angle π/4, argument 3π/4।'))
add(c,'powers-i',lambda n:Q(f'i^{4*n+3}+i^{4*n+1} কত?',0,['2i','−2i',2],'i⁴=1; দুই power যথাক্রমে i³=−i ও i। যোগ শূন্য। cyclic reduction।'))
add(c,'complex-locus',lambda n:Q(f'|z−{n}|=|z+{n}| locus-এর equation কোনটি?','Re(z)=0',['Im(z)=0',f'Re(z)={n}',f'|z|={n}'],'z=x+iy বসিয়ে (x−n)²+y²=(x+n)²+y² ⇒x=0; perpendicular bisector।'))
add(c,'square-root-real-part',lambda n:Q(f'(a+bi)²={n*n-1}+{2*n}i, a>0। a কত?',n,[n*n,n-1,n+1],'(n+i)²=n²−1+2ni। দুই root ±(n+i); positive real part বাছলে a=n।'))
add(c,'cube-roots-sum',lambda n:Q(f'z³={n**3} সমীকরণের তিনটি root-এর যোগ কত?',0,[n,3*n,-n],'Monic cubic z³−n³-এ z² coefficient 0। Vieta অনুযায়ী সব complex root-এর sum=0।'))
add(c,'distance-locus',lambda n:Q(f'|z−({n}+2i)|=3 বৃত্তের কেন্দ্রের modulus² কত?',n*n+4,[9,n*n+9,n*n-4],'Complex plane-এ কেন্দ্র (n,2), radius 3। কেন্দ্রের modulus²=n²+2², radius² নয়।'))

c='math-2-04'
add(c,'reciprocal-root-sum',lambda n:Q(f'x²−{n}x+2=0-এর root α,β। 1/α²+1/β² কত?',F(n*n-4,4),[F(n*n,4),F(n*n-4,2),n*n-4],'α+β=n, αβ=2। sum reciprocal squares=[(α+β)²−2αβ]/(αβ)²=(n²−4)/4।'))
add(c,'shifted-roots',lambda n:Q(f'x²−{n}x+2=0-এর root α,β। root α+1,β+1 বিশিষ্ট monic polynomial-এর constant term কত?',n+3,[n+1,3-n,2*n],'নতুন product=(α+1)(β+1)=αβ+α+β+1=2+n+1=n+3।'))
add(c,'cubic-square-sum',lambda n:Q(f'x³−{n}x²+3x−2=0-এর root α,β,γ। α²+β²+γ² কত?',n*n-6,[n*n+6,n*n-3,3*n],'Vieta: sum=n, pair sum=3। square sum=(sum)²−2(pair sum)=n²−6।'))
add(c,'remainder-two',lambda n:Q(f'P(x) কে x−1 ও x−2 দিয়ে ভাগে remainder {n} ও {n+3}। (x−1)(x−2) দিয়ে ভাগের remainder R(x)=ax+b হলে a কত?',3,[n,n+3,2*n+3],'Linear remainder R(1)=n, R(2)=n+3। বিয়োগে a=3; b=n−3।'),'hard')
add(c,'factor-parameter',lambda n:Q(f'P(x)=x³+kx+{n} এবং x−1 factor। k কত?',-n-1,[n+1,-n,n-1],'Factor theorem P(1)=1+k+n=0। অতএব k=−n−1; root substitute করতে হয়।'))
add(c,'double-root-condition',lambda n:Q(f'x²−{2*n}x+k=0-এর equal roots হতে k কত?',n*n,[2*n,4*n*n,-n*n],'Discriminant (2n)²−4k=0 ⇒k=n²; polynomial=(x−n)²।'))
add(c,'root-difference',lambda n:Q(f'x²−{2*n}x+({n*n-4})=0-এর দুই real root-এর পার্থক্যের absolute value কত?',4,[2,2*n,8],'Discriminant=4n²−4(n²−4)=16। root gap √D/|a|=4।'))
add(c,'cubic-product-reciprocal',lambda n:Q(f'x³−2x²+3x−{n}=0-এর roots α,β,γ। 1/α+1/β+1/γ কত?',F(3,n),[F(2,n),F(n,3),-F(3,n)],'Reciprocal sum=(αβ+βγ+γα)/(αβγ)=3/n। Constant −n অর্থ product +n।'))
add(c,'synthetic-value',lambda n:Q(f'P(x)=x^{n}+x+1। x+1 দিয়ে ভাগের remainder কত?',(-1)**n,[0,2,-2],'Remainder theorem-এ x=−1: P(−1)=(−1)ⁿ−1+1=(−1)ⁿ।'))
add(c,'integer-root-factor',lambda n:Q(f'x³−({n+3})x²+({3*n+2})x−{2*n}=0। দুই root 1,2; তৃতীয় root কত?',n,[n+3,2*n,-n],'Product=2n এবং প্রথম দুই root-এর product 2; তৃতীয় n। sum=1+2+n দিয়েও মেলে।'))

c='math-2-05'
add(c,'middle-coefficient',lambda n:Q(f'(1+x)^{2*n}-এ x^{n}-এর coefficient কোনটি?',f'C({2*n},{n})',[f'C({2*n},{n-1})',str(2*n),str(2**n)],'Binomial general term C(2n,r)xʳ। exponent r=n হলে coefficient C(2n,n)।'))
add(c,'constant-laurent',lambda n:Q(f'(x²+1/x)^{3*n}-এর constant term-এর coefficient কোনটি?',f'C({3*n},{2*n})',[f'C({3*n},{n-1})',str(3*n),str(2**n)],'General exponent=2(3n−r)−r=6n−3r। zero হলে r=2n; coefficient C(3n,2n)।'),'hard')
add(c,'weighted-coefficient',lambda n:Q(f'(1+2x)^{n}-এ x²-এর coefficient কত?',2*n*(n-1),[n*(n-1),4*n,n*n],'C(n,2)·2²=4·n(n−1)/2=2n(n−1)। coefficient ও exponent আলাদা।'))
add(c,'alternating-sum',lambda n:Q(f'Σᵣ₌₀^{n}(−1)ʳ C({n},r) কত?',0,[2**n,1,n],'Binomial theorem-এ (1−1)ⁿ=0, কারণ n>0। alternating coefficients cancel।'))
add(c,'weighted-binomial-sum',lambda n:Q(f'Σᵣ₌₀^{n} r C({n},r) কোনটি?',f'{n}×2^{n-1}',[f'2^{n}',f'{n}×2^{n}',f'{n*n}×2^{n-1}'],'(1+x)ⁿ differentiate: Σr C(n,r)xʳ⁻¹=n(1+x)ⁿ⁻¹। x=1 বসালে n2ⁿ⁻¹।'),'hard')
add(c,'even-coefficient-sum',lambda n:Q(f'(1+x)^{n}-এর even-power coefficients-এর যোগ কোনটি?',f'2^{n-1}',[f'2^{n}',f'2^{n+1}',str(n)],'f(1)=2ⁿ, f(−1)=0। even sum=(f(1)+f(−1))/2=2ⁿ⁻¹।'))
add(c,'ratio-adjacent',lambda n:Q(f'(1+x)^{n+3}-এ x² ও x-এর coefficients-এর ratio কত?',F(n+2,2),[F(n+3,2),n+2,F(2,n+2)],'Ratio C(n+3,2)/C(n+3,1)=(n+2)/2। adjacent binomial relation।'))
add(c,'negative-binomial',lambda n:Q(f'(1−x)⁻² expansion-এ x^{n}-এর coefficient কত? |x|<1',n+1,[n,(-1)**n*(n+1),2**n],'Geometric series differentiate করলে (1−x)⁻²=Σ(r+1)xʳ। তাই coefficient n+1, সব positive।'))
add(c,'mixed-coefficient',lambda n:Q(f'(1+x)^{n}(1−x)-এ x² coefficient কত?',F(n*(n-3),2),[F(n*(n-1),2),F(n*(n+1),2),n],'Product coefficient C(n,2)−C(n,1)=n(n−1)/2−n=n(n−3)/2।'))
add(c,'parameter-coefficient',lambda n:Q(f'(1+ax)^{n}-এ x coefficient {2*n} এবং a>0। x² coefficient কত?',2*n*(n-1),[n*(n-1),4*n*n,2*n],'Linear coefficient na=2n⇒a=2। quadratic C(n,2)a²=2n(n−1)।'))

c='math-2-06'
add(c,'parabola-focus',lambda n:Q(f'y²={4*n}x parabola-এর focus ও directrix-এর দূরত্ব কত?',2*n,[n,4*n,F(n,2)],'y²=4ax-এ focus (a,0), directrix x=−a। তাদের perpendicular distance 2a=2n।'))
add(c,'parabola-tangent',lambda n:Q(f'y²=4x parabola-এর ({n*n},{2*n}) বিন্দুতে tangent slope কত?',F(1,n),[n,F(2,n),F(-1,n)],'Implicit derivative 2y y′=4; y′=2/y। y=2n দিলে 1/n।'))
add(c,'ellipse-focal-distance',lambda n:Q(f'x²/{n*n+9}+y²/9=1 ellipse-এর focal distance-এর বর্গ c² কত?',n*n,[n*n+9,n*n+18,9],'Major semiaxis²=a²=n²+9, minor b²=9। ellipse-এ c²=a²−b²=n²।'))
add(c,'hyperbola-eccentricity',lambda n:Q(f'x²/{n*n}−y²/{3*n*n}=1 hyperbola-এর eccentricity কত?',2,[F(1,2),3,4],'Hyperbola c²=a²+b²=4n²; e=c/a=2। ellipse-এর minus sign এখানে প্রযোজ্য নয়।'))
add(c,'ellipse-area',lambda n:Q(f'x²/{4*n*n}+y²/{n*n}=1 ellipse-এর area/π কত?',2*n*n,[3*n*n,4*n*n,2*n],'Semiaxes a=2n,b=n। ellipse area=πab=2πn²; denominator-ই axis length নয়।'))
add(c,'hyperbola-asymptote',lambda n:Q(f'x²/{n*n}−y²/4=1-এর asymptotes-এর positive slope কত?',F(2,n),[F(n,2),F(4,n*n),F(-2,n)],'Asymptote y=±(b/a)x, a=n,b=2। positive slope 2/n।'))
add(c,'parabola-chord',lambda n:Q(f'y²={4*n}x parabola-এর latus rectum length কত?',4*n,[n,2*n,8*n],'Focus x=n। substitute করলে y=±2n; দুই endpoint-এর দূরত্ব 4n।'))
add(c,'ellipse-tangent-intercept',lambda n:Q(f'x²/{25*n*n}+y²/{25*n*n/4}=1 ellipse-এ ({3*n},{2*n})-এ tangent-এর x-intercept কত?',F(25*n,3),[5*n,F(25*n,4),3*n],'Point satisfies 9/25+16/25=1। tangent xx₁/a²+yy₁/b²=1; y=0⇒x=a²/x₁=25n/3।'),'hard')
add(c,'focus-distance-property',lambda n:Q(f'এক ellipse-এর major axis length {6*n}। পরিধির P থেকে দুই focus-এর দূরত্বের যোগ কত?',6*n,[3*n,12*n,2*n],'Ellipse-এর defining property PF₁+PF₂=2a। major axis=2a=6n; P-এর অবস্থানে যোগ বদলায় না।'))
add(c,'conic-discriminant',lambda n:Q(f'x²−{n}xy−y²=1 কোন ধরনের nondegenerate conic?','Hyperbola',['Ellipse','Parabola','Circle'],'General form-এ A=1,B=−n,C=−1। B²−4AC=n²+4>0, ফলে hyperbola।'),'medium','classification')

c='math-2-07'
add(c,'principal-arcsin',lambda n:Q(f'sin⁻¹(sin({n}π+π/6)) কত?', 'π/6' if n%2==0 else '−π/6',['5π/6','−5π/6','π/2'],'sin(nπ+π/6)=(−1)ⁿ/2। principal arcsin range [−π/2,π/2], তাই ±π/6।'))
add(c,'arctan-addition-branch',lambda n:Q(f'tan⁻¹({n})+tan⁻¹(1/{n}) কত? n>0','π/2',['0','π','π/4'],'দুই acute angle complementary, কারণ tanB=1/tanA। principal arctan branch-এ sum π/2।'))
add(c,'cos-arcsin',lambda n:Q(f'cos(sin⁻¹(1/{n}))-এর বর্গ কত?',F(n*n-1,n*n),[F(1,n*n),F(n*n+1,n*n),F(n-1,n)],'arcsin-এর principal interval-এ cos nonnegative। cos²=1−sin²=1−1/n²।'))
add(c,'equation-root-count',lambda n:Q(f'0≤x<2π-এ sin({n}x)=0 সমীকরণের root কতটি?',2*n,[n,2*n+1,n+1],'nx=mπ; x=mπ/n। allowed m=0,1,…,2n−1, তাই 2n roots; 2π বাদ।'))
add(c,'tan-equation-root-count',lambda n:Q(f'0≤x<π-এ tan({n}x)=1 সমীকরণের root কতটি?',n,[2*n,n+1,1],'nx=π/4+kπ। interval length nπ-এ ঠিক nটি allowed integer k; tangent poles root নয়।'))
add(c,'inverse-sine-sum',lambda n:Q(f'sin⁻¹(1/{n})+cos⁻¹(1/{n}) কত?','π/2',['π','0','π/4'],'Principal inverse functions satisfy arcsin u+arccos u=π/2 for −1≤u≤1।'))
add(c,'inverse-tan-cos',lambda n:Q(f'cos(2tan⁻¹({n})) কত?',F(1-n*n,1+n*n),[F(n*n-1,1+n*n),F(2*n,1+n*n),F(1,1+n*n)],'θ=arctan n⇒tanθ=n। cos2θ=(1−tan²θ)/(1+tan²θ)=(1−n²)/(1+n²)।'))
add(c,'absolute-sine-equation',lambda n:Q(f'0≤x<2π-এ |sinx|=1/{n} সমীকরণের root কতটি?',4,[2,1,8],'0<1/n<1। sinx=±1/n; প্রতিটির দুই root, তাই মোট চারটি distinct root।'))
add(c,'arcsec-domain',lambda n:Q(f'sec⁻¹(x−{n}) বাস্তব হতে x-এর domain কোনটি?',f'(−∞,{n-1}]∪[{n+1},∞)',[f'[{n-1},{n+1}]',f'({n-1},{n+1})',f'ℝ∖{{{n}}}'],'Real arcsec argument-এর |x−n|≥1 লাগবে। দুই disjoint closed outer interval।'))
add(c,'quadratic-sine-filter',lambda n:Q(f'0≤x<2π-এ {n}sin²x−({n+1})sinx+1=0-এর root কতটি?',3,[2,4,1],'Factor (n sinx−1)(sinx−1)=0। sinx=1/n-এর 2 root, sinx=1-এর 1 root; total 3।'),'hard')

c='math-2-08'
add(c,'three-force-equilibrium',lambda n:Q(f'Equilibrium-এ F₁=({n},0), F₂=(0,{n}) N। তৃতীয় বলের magnitude² কত?',2*n*n,[n*n,4*n*n,2*n],'F₃=−(F₁+F₂)=(−n,−n)। magnitude²=n²+n²=2n²।'))
add(c,'moment-balance',lambda n:Q(f'Weightless lever-এর pivot থেকে বামে {n} m-এ 20 N, ডানে 2 m-এ W। equilibrium-এ W কত N?',10*n,[20*n,F(20,n),40*n],'Moments balance: 20·n=W·2। তাই W=10n; clockwise/counterclockwise opposite।'))
add(c,'ladder-smooth-wall',lambda n:Q(f'Uniform ladder-এর weight {n*10} N; floor-এর সঙ্গে 45°। wall smooth। wall reaction কত N?',5*n,[10*n,20*n,F(5*n,2)],'Foot-এর about torque: Rwall·L sin45°=W(L/2)cos45°। Rwall=W/2=5n।'),'hard')
add(c,'two-supports',lambda n:Q(f'Weightless beam length 6 m। বাম প্রান্ত থেকে 2 m-এ {3*n} N load। ডান support reaction কত N?',n,[2*n,3*n,F(n,2)],'বাম support-এর about moment: Rright·6=3n·2। Rright=n; অন্য reaction 2n।'))
add(c,'incline-friction-threshold',lambda n:Q(f'Block incline-এ equilibrium-এ, tanθ=1/{n}। impending downward slip-এ μs কত?',F(1,n),[n,F(1,n*n),F(2,n)],'Threshold mg sinθ=μs mg cosθ। তাই μs=tanθ=1/n; mass cancel।'))
add(c,'couple-moment',lambda n:Q(f'Opposite parallel forces {n} N each, perpendicular separation 3 m। couple moment কত N·m?',3*n,[6*n,0,n],'Couple-এর resultant force zero হলেও torque F×separation=3n। দুই force-এর torque আলাদাভাবে double করতে হয় না।'))
add(c,'incline-normal',lambda n:Q(f'Weight {5*n} N block 3:4:5 incline-এ, sinθ=3/5। normal reaction কত N?',4*n,[3*n,5*n,F(15*n,4)],'Incline-normal equilibrium N=W cosθ। cosθ=4/5; N=5n·4/5=4n।'))
add(c,'rope-tension-horizontal',lambda n:Q(f'Weight {6*n} N দুই symmetric rope দিয়ে ঝোলে; প্রতিটি vertical-এর সঙ্গে 60°। প্রতিটির tension কত N?',6*n,[3*n,12*n,F(3*n,2)],'Vertical components 2T cos60°=W। cos60°=½ থেকে T=W=6n; horizontal components cancel।'))
add(c,'force-resultant-angle',lambda n:Q(f'দুটি সমান {n} N বলের resultant {n} N। তাদের মধ্যবর্তী কোণ কত?','120°',['60°','90°','180°'],'R²=F²+F²+2F²cosθ। R=F⇒1=2+2cosθ⇒cosθ=−½⇒120°।'))
add(c,'centre-of-mass-balance',lambda n:Q(f'x=0-এ mass {n} kg, x=6 m-এ mass {2*n} kg। centre of mass x কত m?',4,[2,3,6],'xcm=(n·0+2n·6)/(3n)=4 m। heavier mass-এর দিকে weighted mean যায়।'))

c='math-2-09'
add(c,'projectile-height-range',lambda n:Q(f'Projectile-এর range R={8*n} m ও maximum height H={n} m। tanθ কত?',F(1,2),[2,F(1,4),1],'R/H=[u²sin2θ/g]/[u²sin²θ/(2g)]=4cotθ। তাই tanθ=4H/R=½।'))
add(c,'projectile-at-half-time',lambda n:Q(f'Projectile-এর flight time {2*n} s, g=10 m/s²। launch-এর {n} s পরে vertical velocity কত?',0,[10*n,-10*n,5*n],'Same-level flight T=2uy/g⇒uy=10n। at t=n, vy=uy−gt=0; সর্বোচ্চ বিন্দু।'))
add(c,'horizontal-throw',lambda n:Q(f'উচ্চতা {5*n*n} m থেকে horizontal speed 3 m/s-এ নিক্ষেপ; g=10। landing পর্যন্ত horizontal distance কত m?',3*n,[5*n,3*n*n,F(3*n,2)],'Vertical fall h=½gt²=5t²⇒t=n। horizontal velocity constant 3; distance=3n।'))
add(c,'relative-speed',lambda n:Q(f'দুটি particle-এর velocities ({n},0) ও (0,{n}) m/s। relative speed² কত?',2*n*n,[0,n*n,4*n*n],'Relative velocity v₁−v₂=(n,−n)। speed²=2n²; speed difference শূন্য নয়।'))
add(c,'range-complementary',lambda n:Q(f'Same speed-এ angles θ ও 90°−θ-তে projectile range-এর ratio কত? speed={n} m/s',1,[2,F(1,2),0],'R∝sin2θ। complementary angle-এ sin(180°−2θ)=sin2θ; range identical।'),'medium','conceptual')
add(c,'circular-tangent',lambda n:Q(f'Uniform circular motion-এ radius {n} m, angular speed 2 rad/s। acceleration magnitude কত?',4*n,[2*n,4*n*n,0],'Centripetal acceleration a=ω²r=4n। speed constant হলেও velocity direction বদলায়।'))
add(c,'projectile-velocity-ratio',lambda n:Q(f'Projectile launched velocity ({3*n},{4*n}) m/s। maximum height-এ speed/initial speed কত?',F(3,5),[F(4,5),0,1],'At top vertical velocity zero, horizontal remains 3n; initial speed=5n। ratio=3/5।'))
add(c,'time-elimination',lambda n:Q(f'x=2t, y={n}t−t²। path-এর y(x) কোনটি?',f'y={fmt(F(n,2))}x−x²/4',[f'y={n}x−x²',f'y={fmt(F(n,2))}x−x²/2',f'y={n}x−x²/4'],'x=2t⇒t=x/2। substitute y=nx/2−x²/4; trajectory parabola।'))
add(c,'range-inverse',lambda n:Q(f'45° launch, speed {n} m/s, g=10। range কত m?',F(n*n,10),[F(n*n,20),F(n,10),n*n],'R=u² sin90°/g=u²/g=n²/10। Maximum-height formula নিলে factor 4 ভুল হবে।'))
add(c,'uniform-accel-vector',lambda n:Q(f'v₀=(1,2), a=(2,−1) m/s²। t={n} s-এ v·a কত?',5*n,[5*n+4,5*n-4,n],'v=v₀+at। v₀·a=2−2=0 ও |a|²=5; v·a=5t=5n।'),'hard')

c='math-2-10'
add(c,'conditional-probability',lambda n:Q(f'Bag-এ {n} red, {n+1} blue বল। replacement ছাড়া প্রথম বল red জানা আছে। দ্বিতীয়ও red-এর probability কত?',F(n-1,2*n),[F(n,2*n+1),F(n,2*n),F(n-1,2*n+1)],'প্রথম red সরানোর পরে red n−1, মোট 2n। conditional probability=(n−1)/(2n)।'))
add(c,'at-least-one-success',lambda n:Q(f'Independent trial-এ success probability 1/{n}। দুই trial-এ অন্তত একটি success-এর probability কত?',F(2*n-1,n*n),[F(2,n),F(1,n*n),F((n-1)**2,n*n)],'Complement: 1−P(no success)=1−(1−1/n)²=(2n−1)/n²।'))
add(c,'bayes',lambda n:Q(f'Factory A মোট 1/3 item বানায়, defect rate 1/{n}; B বাকি 2/3, defect rate 1/{2*n}। defective item A-এর probability কত?',F(1,2),[F(1,3),F(2,3),F(1,n)],'Bayes numerator (1/3)(1/n)=1/(3n)। B defective contribution একই 1/(3n); posterior=½।'),'hard','conditional')
add(c,'variance-shift-scale',lambda n:Q(f'Var(X)={n}। Y=3X+7 হলে Var(Y) কত?',9*n,[3*n,9*n+7,n+7],'Variance translation-এ বদলায় না, scaling-এর square লাগে: Var(aX+b)=a²Var(X)=9n।'))
add(c,'uniform-mean',lambda n:Q(f'X uniform discrete on {{1,2,…,{n}}}। E(X) কত?',F(n+1,2),[F(n,2),n,F(n*(n+1),2)],'Equal probabilities 1/n; E=Σk/n=[n(n+1)/2]/n=(n+1)/2।'))
add(c,'binomial-exact',lambda n:Q(f'3 independent trials, success probability 1/{n}। exactly 2 successes-এর probability কত?',F(3*(n-1),n**3),[F(n-1,n**3),F(3,n*n),F(1,n**3)],'Binomial: C(3,2)p²(1−p)=3(1/n²)((n−1)/n)=3(n−1)/n³।'))
add(c,'total-probability',lambda n:Q(f'P(A)=1/4, P(B|A)=1/{n}, P(B|Aᶜ)=2/{n}। P(B) কত?',F(7,4*n),[F(3,n),F(1,4*n),F(1,n)],'Law of total probability: P(B)=¼(1/n)+¾(2/n)=7/(4n)। A ও complement exhaust sample space।'))
add(c,'variance-pair',lambda n:Q(f'Population data {{0,{n},{2*n}}}। variance কত?',F(2*n*n,3),[n*n,F(n*n,3),2*n*n],'Mean=n। squared deviations n²,0,n²; population variance=sum/3=2n²/3।'))
add(c,'union-independent',lambda n:Q(f'Independent A,B: P(A)=1/{n}, P(B)=1/2। P(A∪B) কত?',F(n+1,2*n),[F(n+2,2*n),F(1,2*n),F(n-1,2*n)],'Union=P(A)+P(B)−P(A)P(B)=1/n+½−1/(2n)=(n+1)/(2n)।'))
add(c,'hypergeometric',lambda n:Q(f'{n} red ও 2 blue বল থেকে দুইটি একসঙ্গে তোলা। দুটিই blue-এর probability কত?',F(2,(n+2)*(n+1)),[F(4,(n+2)**2),F(2,n+2),F(1,n+2)],'দুই blue বাছার উপায় 1; মোট pair C(n+2,2)। probability=1/C(n+2,2)=2/[(n+2)(n+1)]।'))
